let doc = null;
let selected = null;
let customCss = '';
let workspaceData = null;
let activeWorkspace = null;
let cssWasOpen = false;
let currentView = 'preview';
let activeRoute = new URLSearchParams(location.search).get('view') || 'overview';
const workspaceStateKey = () => `becky-admin-workspace-state-${activeRoute}`;
const sidebarStateKey = 'becky-admin-sidebar-open';
const $ = id => document.getElementById(id);
const adminSessionKey = 'becky-admin-session';
let adminSession = (() => {
  try { return JSON.parse(sessionStorage.getItem(adminSessionKey) || 'null'); }
  catch { return null; }
})();
function saveAdminSession(session) {
  adminSession = session;
  if (session) sessionStorage.setItem(adminSessionKey, JSON.stringify(session));
  else sessionStorage.removeItem(adminSessionKey);
}
async function refreshAdminSession() {
  if (!adminSession?.refresh_token) return false;
  const response = await fetch('/api/auth/refresh', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ refresh_token: adminSession.refresh_token })
  });
  if (!response.ok) { saveAdminSession(null); return false; }
  saveAdminSession(await response.json());
  return true;
}
async function apiFetch(path, options = {}) {
  const headers = new Headers(options.headers || {});
  if (adminSession?.access_token) headers.set('Authorization', `Bearer ${adminSession.access_token}`);
  let response = await fetch(path, { ...options, headers });
  if (response.status === 401 && adminSession?.refresh_token && await refreshAdminSession()) {
    headers.set('Authorization', `Bearer ${adminSession.access_token}`);
    response = await fetch(path, { ...options, headers });
  }
  return response;
}
window.adminApiFetch = apiFetch;
function showAdminLogin(message = '') {
  document.documentElement.classList.remove('booting');
  let overlay = $('admin-login');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'admin-login';
    overlay.className = 'admin-login';
    overlay.innerHTML = `<form class="admin-login-card"><img src="/assets/logo-mark-sun.png" alt=""><span class="eyebrow">BECKY’S GARDEN · ADMIN</span><h1>Intră în panoul de administrare</h1><p>Folosește contul autorizat pentru acest spațiu.</p><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Parolă<input type="password" name="password" autocomplete="current-password" required></label><div class="admin-login-error" aria-live="polite"></div><button class="primary" type="submit">Autentifică-mă</button></form>`;
    document.body.appendChild(overlay);
    overlay.querySelector('form').addEventListener('submit', async event => {
      event.preventDefault();
      const form = event.currentTarget;
      const button = form.querySelector('button');
      const error = form.querySelector('.admin-login-error');
      button.disabled = true;
      button.textContent = 'Se verifică…';
      error.textContent = '';
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: form.email.value.trim(), password: form.password.value })
      });
      if (response.ok) {
        saveAdminSession(await response.json());
        overlay.remove();
        await load();
        return;
      }
      const result = await response.json().catch(() => ({}));
      error.textContent = result.error || 'Autentificarea nu a reușit.';
      button.disabled = false;
      button.textContent = 'Autentifică-mă';
    });
  }
  overlay.querySelector('.admin-login-error').textContent = message;
  overlay.querySelector('input')?.focus();
}
async function startAdmin() {
  const runtime = await fetch('/api/runtime').then(response => response.ok ? response.json() : { authRequired: true }).catch(() => ({ authRequired: true }));
  if (!runtime.authRequired) {
    await load();
    return;
  }
  if (!adminSession?.access_token) { showAdminLogin(); return; }
  const check = await apiFetch('/api/auth/me');
  if (!check.ok) {
    saveAdminSession(null);
    showAdminLogin('Sesiunea a expirat. Autentifică-te din nou.');
    return;
  }
  await load();
}
