function blockKind(block) { return ({overview:'Introducere','strategy-update':'Direcție strategică',chapter:'Capitol',appendix:'Anexă',section:'Secțiune',menu:'Meniu'})[block.type]||block.type||'Conținut'; }
function label(block) { return outlineInfo(block).title; }
