function persistWorkspaceState() { localStorage.setItem(workspaceStateKey(), JSON.stringify({selected,currentView,cssWasOpen,outlineScroll:$('outline')?.scrollTop||0,codeScroll:$('code')?.scrollTop||0,previewScroll:$('preview')?.scrollTop||0,cssScroll:$('css-code')?.scrollTop||0})); }
function select(index) { selected=index; const block=doc.blocks[index]; $('css-workspace').classList.add('hidden'); $('empty').classList.add('hidden'); $('editor').classList.remove('hidden'); $('editor-title').textContent=label(block); $('block-type').textContent=blockKind(block).toUpperCase(); $('block-id').textContent=block.id||''; $('code').value=block.html; renderPreview(block.html); const previewing=currentView==='preview';$('code').classList.toggle('hidden',previewing);$('preview').classList.toggle('hidden',!previewing);document.querySelectorAll('.toggle').forEach(x=>x.classList.toggle('active',x.dataset.view===currentView));renderOutline(); requestAnimationFrame(()=>{const panel=document.querySelector('.editor-panel');if(panel)panel.scrollTop=0;$('editor').scrollTop=0;$('code').scrollTop=0;$('preview').scrollTop=0;}); persistWorkspaceState(); }
