async function navigateWorkspace(route) { if(route===activeRoute){if(route==='content')window.renderContentCreator?.({home:true});if(route==='children')await window.renderChildrenActivityEditor?.();if(route==='calendar')await window.renderCalendarAdmin?.();if(route==='inbox')await window.renderInboxAdmin?.();return;} persistWorkspaceState();activeRoute=route;history.pushState({},'',route==='manual'?'/admin?view=manual':`/admin?view=${route}`);selected=null;cssWasOpen=false;currentView='preview';if(route==='content'){window.renderContentCreator?.({home:true});return;}if(route==='children'){await window.renderChildrenActivityEditor?.();return;}if(route==='calendar'){await window.renderCalendarAdmin?.();return;}if(route==='inbox'){await window.renderInboxAdmin?.();return;}const manualResponse=await apiFetch('/api/manual');doc=await manualResponse.json();if(route==='overview'){renderOverviewHub();return;}loadWorkspaceContext();applyWorkspaceColorOverrides();renderOutline();$('css-workspace').classList.add('hidden');$('empty').classList.add('hidden');$('workspace-demo')?.classList.add('hidden');document.querySelector('.workspace')?.classList.remove('hidden');$('editor').classList.remove('hidden');if(doc.blocks.length)select(0);}
