function localOverviewTasks(){try{const saved=JSON.parse(localStorage.getItem(overviewKey)||'null');if(Array.isArray(saved))return saved}catch{}return defaultOverviewTasks.map(x=>({...x}));}
function overviewTasks(){return overviewBackendTasks||localOverviewTasks();}
async function hydrateOverviewTasks(){
  try {
    const response=await apiFetch('/api/admin/tasks');
    if(!response.ok)throw new Error('Task API unavailable');
    const payload=await response.json();
    const tasks=Array.isArray(payload.tasks)?payload.tasks:[];
    if(!localStorage.getItem(overviewMigrationKey)&&tasks.length===0){
      const legacy=localStorage.getItem(overviewKey)?localOverviewTasks():defaultOverviewTasks.map(x=>({...x}));
      if(legacy.length){
        const imported=await apiFetch('/api/admin/tasks',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({tasks:legacy.map((task,index)=>({...task,sort_order:index}))})});
        if(imported.ok){const importedPayload=await imported.json();overviewBackendTasks=Array.isArray(importedPayload.tasks)?importedPayload.tasks:legacy;localStorage.setItem(overviewMigrationKey,'1');return;}
      }
      localStorage.setItem(overviewMigrationKey,'1');
    }
    overviewBackendTasks=tasks;
  } catch { overviewBackendTasks=null; }
}
async function saveOverviewTasks(tasks){
  const next=tasks.map((task,index)=>({...task,sort_order:index}));
  localStorage.setItem(overviewKey,JSON.stringify(next));
  try { const response=await apiFetch('/api/admin/tasks',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({tasks:next})});if(!response.ok)throw new Error('Task save failed');const payload=await response.json();overviewBackendTasks=Array.isArray(payload.tasks)?payload.tasks:next;return true; } catch { overviewBackendTasks=next;return false; }
}
