async function renderOverviewHub(){const demo=$('workspace-demo');if(!demo)return;document.body.dataset.workspace='overview';document.querySelector('.workspace')?.classList.add('hidden');$('css-workspace')?.classList.add('hidden');$('empty')?.classList.add('hidden');$('editor')?.classList.add('hidden');demo.className='workspace-demo overview-hub-workspace';demo.classList.remove('hidden');document.querySelector('.topbar h1').textContent='Overview Becky Friends';document.querySelector('.topbar .subtitle').textContent='Alege zona în care vrei să intri. Overview-ul poate crește odată cu proiectul.';document.querySelector('.top-actions')?.classList.add('overview-actions-hidden');document.querySelectorAll('.sidebar .side-link').forEach(link=>link.classList.toggle('active',link.classList.contains('overview-link')));const taskCount=overviewTasks().length;demo.innerHTML=`<div class="overview-hub-head"><span>ADMIN / OVERVIEW</span><h2>Ce vrei să urmărești<br><em>astăzi?</em></h2><p>Taskurile și fiecare sursă de insight au propriul spațiu. Module noi pot fi adăugate fără să aglomerăm dashboardurile existente.</p></div><div class="overview-module-grid"><a class="overview-module task-module" href="/admin?view=overview-tasks"><div class="overview-module-icon">✓</div><small>EXECUȚIE</small><h3>Taskuri și priorități</h3><p>Boardul de lucru pentru decizii, responsabilități și pașii următori.</p><footer><strong>${taskCount} taskuri</strong><span>Deschide boardul →</span></footer></a><a class="overview-module event-module" href="/admin?view=events"><div class="overview-module-icon">🎈</div><small>CERCETARE</small><h3>Chestionar evenimente</h3><p>Motivații, fricțiuni, program și conceptele preferate de familii.</p><footer><strong data-overview-event-count>Se încarcă…</strong><span>Vezi insighturile →</span></footer></a><a class="overview-module playground-module" href="/admin?view=playground"><div class="overview-module-icon">🛝</div><small>CERCETARE · NOU</small><h3>Chestionar loc de joacă</h3><p>Ce apreciază vizitatorii, ce lipsește și ce îi face să revină.</p><footer><strong data-overview-playground-count>Se încarcă…</strong><span>Vezi insighturile →</span></footer></a><article class="overview-module future-module"><div class="overview-module-icon">＋</div><small>ARHITECTURĂ EXTENSIBILĂ</small><h3>Următorul modul</h3><p>Evenimente viitoare, petreceri sau orice altă zonă importantă va avea loc aici.</p><footer><strong>Pregătit pentru extindere</strong></footer></article></div>`;try{const [events,playground]=await Promise.all([apiFetch('/api/event-survey/results'),apiFetch('/api/playground-survey/results')]);if(events.ok){const payload=await events.json();document.querySelector('[data-overview-event-count]').textContent=`${Array.isArray(payload.responses)?payload.responses.length:0} răspunsuri`;}if(playground.ok){const payload=await playground.json();document.querySelector('[data-overview-playground-count]').textContent=`${Array.isArray(payload.responses)?payload.responses.length:0} răspunsuri`;}}catch{document.querySelectorAll('[data-overview-event-count],[data-overview-playground-count]').forEach(node=>node.textContent='Date indisponibile');}}
const overviewCalendarMeta={open:['🟢','acces liber'],party:['🎂','acces public'],event:['🎈','acces public'],reservation:['🗺️','rezervare'],private:['🎂','acces închis'],closed:['🔒','închis']};
const overviewCalendarSafe=value=>escapeHtml(String(value??''));
const overviewCalendarDate=value=>new Intl.DateTimeFormat('ro-RO',{weekday:'long',day:'numeric',month:'long'}).format(new Date(`${value}T12:00:00`));
const overviewLocalDate=()=>{const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`};
function overviewCalendarLines(entries){
  const today=overviewLocalDate();
  const upcoming=[...entries].filter(entry=>entry.date>=today).sort((a,b)=>`${a.date}T${a.start_time}`.localeCompare(`${b.date}T${b.start_time}`));
  const todayEntries=upcoming.filter(entry=>entry.date===today);
  const futureEntries=upcoming.filter(entry=>entry.date!==today).slice(0,4);
  const line=entry=>{const meta=overviewCalendarMeta[entry.type]||['•',''];return `<div class="overview-calendar-line"><strong>${entry.date===today?'Astăzi':overviewCalendarDate(entry.date)}</strong><span>${overviewCalendarSafe(entry.start_time)}–${overviewCalendarSafe(entry.end_time)} · ${meta[0]} ${overviewCalendarSafe(entry.title)}</span><small>${meta[1]}</small></div>`};
  return [...todayEntries,...futureEntries].map(line).join('')||'<p class="overview-no-data">Nu există încă date.</p>';
}
