async function renderOverviewHubWithInbox(){await overviewHubWithoutInbox();const card=[...document.querySelectorAll('.overview-final-card')].find(item=>item.querySelector('h3')?.textContent.trim()==='Inbox');if(!card)return;let events=[],playground=[];try{const [eventResponse,playgroundResponse]=await Promise.all([apiFetch('/api/event-survey/results'),apiFetch('/api/playground-survey/results')]);if(eventResponse.ok)events=inboxSourceRows(await eventResponse.json(),'Evenimente','🎈');if(playgroundResponse.ok)playground=inboxSourceRows(await playgroundResponse.json(),'Experiență Becky','🛝');}catch{}const since=Date.now()-7*86400000;const recent=[...events,...playground].filter(row=>new Date(row.date).getTime()>=since);const all=[...events,...playground].sort((a,b)=>new Date(b.date)-new Date(a.date));const latest=all[0];card.classList.add('overview-inbox-card');card.setAttribute('role','link');card.setAttribute('tabindex','0');card.setAttribute('aria-label','Deschide Inbox');card.innerHTML=`<header><span class="overview-final-icon">📥</span><div><small>MESaje</small><h3>Inbox</h3></div><b>→</b></header><div class="overview-inbox-summary"><strong>${recent.length} ${recent.length===1?'intrare nouă':'intrări noi'} în ultimele 7 zile</strong><span>${events.filter(row=>new Date(row.date).getTime()>=since).length} ${'🎈'} Evenimente</span><span>${playground.filter(row=>new Date(row.date).getTime()>=since).length} ${'🛝'} Experiență Becky</span><small>${latest?`Ultima: ${inboxLatestLabel(latest.date)}`:'Nu există încă date.'}</small></div><footer>Deschide Inbox-ul</footer>`;const go=()=>{window.location.href='/admin?view=inbox'};card.addEventListener('click',go);card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();go()}});}
renderOverviewHub=renderOverviewHubWithInbox;
function overviewTemplate(tasks,filter=overviewFilter){const byPriority=filter==='all'?tasks:tasks.filter(task=>task.priority===filter);const visibleTasks=overviewOwnerFilter==='all'?byPriority:byPriority.filter(task=>overviewOwnerFilter==='mine'?task.owner!=='together':task.owner==='together');return `<div class="overview-wrap"><div class="overview-hero"><div><span class="eyebrow">ADMIN / OVERVIEW</span><h2>Ce construim pentru Becky <em>acum?</em></h2><p>Un board viu pentru tot ce am început, tot ce lipsește și tot ce merită discutat împreună.</p></div><button class="overview-add" data-overview-add>＋ Adaugă task</button></div><div class="overview-filters" role="group" aria-label="Filtrează taskurile"><span>Arată-mi</span><button class="overview-filter ${filter==='all'?'is-active':''}" data-overview-filter="all">Toate</button><button class="overview-filter ${filter==='high'?'is-active':''}" data-overview-filter="high">Acum</button><button class="overview-filter ${filter==='medium'?'is-active':''}" data-overview-filter="medium">Următorul pas</button><button class="overview-filter ${filter==='low'?'is-active':''}" data-overview-filter="low">Când avem spațiu</button></div><div class="overview-filters overview-owner-filters" role="group" aria-label="Filtrează responsabilitatea"><span>Responsabilitate</span><button class="overview-filter ${overviewOwnerFilter==='all'?'is-active':''}" data-overview-owner-filter="all">Toate</button><button class="overview-filter ${overviewOwnerFilter==='mine'?'is-active':''}" data-overview-owner-filter="mine">Radu</button><button class="overview-filter ${overviewOwnerFilter==='together'?'is-active':''}" data-overview-owner-filter="together">Discutăm împreună</button></div><div class="overview-legend"><span><i class="legend-dot dot-you"></i>Radu + Codex</span><span><i class="legend-dot dot-together"></i>Discutăm împreună</span><span class="overview-count">${visibleTasks.length} din ${tasks.length} taskuri · salvare locală</span></div><div class="overview-board">${overviewAreas.map(area=>{const cards=visibleTasks.filter(task=>task.area===area.id);return `<section class="overview-column" data-area="${area.id}" style="--area-color:${area.color}"><header><div class="overview-column-icon">${area.icon}</div><div><h3>${area.label}</h3><p>${area.hint}</p></div><b>${cards.length}</b></header><div class="overview-dropzone">${cards.map(task=>`<article class="overview-card" draggable="true" data-owner="${task.owner}" data-task-id="${task.id}"><div class="overview-card-top"><span class="overview-priority priority-${task.priority}">${overviewPriority(task.priority)}</span><button class="overview-edit" data-overview-edit="${task.id}" aria-label="Editează task">···</button></div><h4>${escapeHtml(task.title)}</h4><p>${escapeHtml(task.detail)}</p><footer><span class="owner-chip owner-chip-${task.owner}">${overviewOwner(task.owner)}</span></footer></article>`).join('')||'<div class="overview-empty">Niciun task în filtrul acesta.<br>Poți schimba filtrul sau adăuga unul nou.</div>'}</div></section>`}).join('')}</div></div><div class="overview-modal hidden" id="overview-modal"><form class="overview-modal-card" id="overview-form"><div class="overview-modal-head"><div><span class="eyebrow">TASK BECKY</span><h3 id="overview-modal-title">Task nou</h3></div><button type="button" class="overview-close" data-overview-close>×</button></div><label>Titlu<input name="title" required maxlength="120"></label><label>Context / rezultat dorit<textarea name="detail" maxlength="280"></textarea></label><div class="overview-form-grid"><label>Arie<select name="area">${overviewAreas.map(a=>`<option value="${a.id}">${a.label}</option>`).join('')}</select></label><label>Cine îl ține<select name="owner"><option value="you">Radu</option><option value="us">Codex</option><option value="together">Împreună</option></select></label><label>Prioritate<select name="priority"><option value="high">Acum</option><option value="medium">Următorul pas</option><option value="low">Când avem spațiu</option></select></label></div><div class="overview-modal-actions"><button type="button" class="overview-delete hidden" data-overview-delete>Șterge task</button><button type="button" class="secondary" data-overview-close>Anulează</button><button class="primary" type="submit">Salvează task</button></div></form></div>`}
function renderOverview(){const demo=$('workspace-demo');if(!demo)return;const tasks=overviewTasks();document.body.dataset.workspace='overview';document.querySelectorAll('.sidebar .side-link').forEach(link=>link.classList.toggle('active',link.classList.contains('overview-link')));document.querySelector('.workspace')?.classList.add('hidden');$('css-workspace')?.classList.add('hidden');$('empty')?.classList.add('hidden');$('editor')?.classList.add('hidden');demo.classList.remove('hidden');document.querySelector('.topbar h1').textContent='Taskuri și priorități';document.querySelector('.topbar .subtitle').textContent='Un board viu pentru decizii, execuție și discuții.';document.querySelector('.top-actions')?.classList.add('overview-actions-hidden');demo.innerHTML=overviewTemplate(tasks,overviewFilter);const hero=demo.querySelector('.overview-hero');if(hero)hero.insertAdjacentHTML('beforeend','<a class="overview-hub-back" href="/admin?view=overview">← Înapoi la Overview</a>');bindOverview(tasks)}
function bindOverview(tasks){const modal=$('overview-modal');let editing=null;const open=(task)=>{editing=task||null;modal.classList.remove('hidden');const form=$('overview-form');form.title.value=task?.title||'';form.detail.value=task?.detail||'';form.area.value=task?.area||'technical';form.owner.value=task?.owner||'together';form.priority.value=task?.priority||'medium';$('overview-modal-title').textContent=task?'Bewerk task':'Nieuw task';document.querySelector('[data-overview-delete]')?.classList.toggle('hidden',!task);form.title.focus()};document.querySelectorAll('[data-overview-filter]').forEach(button=>button.addEventListener('click',()=>{overviewFilter=button.dataset.overviewFilter;renderOverview()}));document.querySelectorAll('[data-overview-owner-filter]').forEach(button=>button.addEventListener('click',()=>{overviewOwnerFilter=button.dataset.overviewOwnerFilter;renderOverview()}));document.querySelector('[data-overview-add]')?.addEventListener('click',()=>open());document.querySelectorAll('[data-overview-edit]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();open(tasks.find(x=>x.id===button.dataset.overviewEdit))}));document.querySelectorAll('[data-overview-close]').forEach(button=>button.addEventListener('click',()=>modal.classList.add('hidden')));document.querySelector('[data-overview-delete]')?.addEventListener('click',()=>{if(!editing)return;saveOverviewTasks(tasks.filter(x=>x.id!==editing.id));renderOverview()});$('overview-form').addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget);const payload={title:form.get('title').trim(),detail:form.get('detail').trim(),area:form.get('area'),owner:form.get('owner'),priority:form.get('priority')};if(editing)Object.assign(editing,payload);else tasks.push({id:'ov-'+Date.now(),...payload});saveOverviewTasks(tasks);renderOverview()});document.querySelectorAll('.overview-card').forEach(card=>{card.addEventListener('dragstart',event=>{event.dataTransfer.setData('text/plain',card.dataset.taskId);card.classList.add('is-dragging')});card.addEventListener('dragend',()=>card.classList.remove('is-dragging'));card.addEventListener('dragover',event=>{event.preventDefault();event.stopPropagation()});card.addEventListener('drop',event=>{event.preventDefault();event.stopPropagation();const draggedId=event.dataTransfer.getData('text/plain');const dragged=tasks.find(x=>x.id===draggedId);const target=tasks.find(x=>x.id===card.dataset.taskId);if(!dragged||!target||dragged.id===target.id)return;tasks.splice(tasks.indexOf(dragged),1);dragged.area=target.area;tasks.splice(tasks.indexOf(target),0,dragged);saveOverviewTasks(tasks);renderOverview()})});document.querySelectorAll('.overview-column').forEach(column=>{column.addEventListener('dragover',event=>{event.preventDefault();column.classList.add('is-over')});column.addEventListener('dragleave',()=>column.classList.remove('is-over'));column.addEventListener('drop',event=>{event.preventDefault();column.classList.remove('is-over');const task=tasks.find(x=>x.id===event.dataTransfer.getData('text/plain'));if(task){task.area=column.dataset.area;saveOverviewTasks(tasks);renderOverview()}})})}
async function bindOverview(tasks){
  const modal=$('overview-modal');let editing=null;
  const open=task=>{editing=task||null;modal.classList.remove('hidden');const form=$('overview-form');form.title.value=task?.title||'';form.detail.value=task?.detail||'';form.area.value=task?.area||'technical';form.owner.value=task?.owner||'together';form.priority.value=task?.priority||'medium';$('overview-modal-title').textContent=task?'Bewerk task':'Nieuw task';document.querySelector('[data-overview-delete]')?.classList.toggle('hidden',!task);form.title.focus()};
  const commit=async next=>{await saveOverviewTasks(next);renderOverview()};
  document.querySelectorAll('[data-overview-filter]').forEach(button=>button.addEventListener('click',()=>{overviewFilter=button.dataset.overviewFilter;renderOverview()}));
  document.querySelectorAll('[data-overview-owner-filter]').forEach(button=>button.addEventListener('click',()=>{overviewOwnerFilter=button.dataset.overviewOwnerFilter;renderOverview()}));
  document.querySelector('[data-overview-add]')?.addEventListener('click',()=>open());
  document.querySelectorAll('[data-overview-edit]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();open(tasks.find(x=>x.id===button.dataset.overviewEdit))}));
  document.querySelectorAll('[data-overview-close]').forEach(button=>button.addEventListener('click',()=>modal.classList.add('hidden')));
  document.querySelector('[data-overview-delete]')?.addEventListener('click',async()=>{if(!editing)return;await commit(tasks.filter(x=>x.id!==editing.id))});
  $('overview-form').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const payload={title:form.get('title').trim(),detail:form.get('detail').trim(),area:form.get('area'),owner:form.get('owner'),priority:form.get('priority')};const next=tasks.map(task=>task.id===editing?.id?{...task,...payload}:task);if(!editing)next.push({id:'ov-'+Date.now(),...payload});await commit(next)});
  document.querySelectorAll('.overview-card').forEach(card=>{card.addEventListener('dragstart',event=>{event.dataTransfer.setData('text/plain',card.dataset.taskId);card.classList.add('is-dragging')});card.addEventListener('dragend',()=>card.classList.remove('is-dragging'));card.addEventListener('dragover',event=>{event.preventDefault();event.stopPropagation()});card.addEventListener('drop',async event=>{event.preventDefault();event.stopPropagation();const draggedId=event.dataTransfer.getData('text/plain');const dragged=tasks.find(x=>x.id===draggedId);const target=tasks.find(x=>x.id===card.dataset.taskId);if(!dragged||!target||dragged.id===target.id)return;const next=tasks.filter(task=>task.id!==dragged.id);dragged.area=target.area;next.splice(next.findIndex(task=>task.id===target.id),0,dragged);await commit(next)})});
  document.querySelectorAll('.overview-column').forEach(column=>{column.addEventListener('dragover',event=>{event.preventDefault();column.classList.add('is-over')});column.addEventListener('dragleave',()=>column.classList.remove('is-over'));column.addEventListener('drop',async event=>{event.preventDefault();column.classList.remove('is-over');const task=tasks.find(x=>x.id===event.dataTransfer.getData('text/plain'));if(task){task.area=column.dataset.area;await commit(tasks)}})});
}
function ensurePublicSiteLink(){const link=document.querySelector('.app-shell>.public-site-link');const sidebar=document.querySelector('.sidebar');if(!link||!sidebar)return;sidebar.insertBefore(link,sidebar.firstChild)}
ensurePublicSiteLink();
